create database netflix_db;
use netflix_db;

CREATE TABLE netflix (
    show_id VARCHAR(10),
    type VARCHAR(10),
    title VARCHAR(255),
    director VARCHAR(255),
    cast TEXT,
    country VARCHAR(255),
    date_added VARCHAR(50),
    release_year INT,
    rating VARCHAR(15),
    duration VARCHAR(50),
    listed_in VARCHAR(255),
    description TEXT
);


select * from netflix;

--  15 Business Problems & Solutions

-- 1. Count the number of Movies vs TV Shows
select type, count(*) as total_content from netflix group by type;

-- 2. Find the most common rating for movies and TV shows
WITH RatingCounts AS (
    SELECT type, rating, COUNT(*) as count,
           RANK() OVER(PARTITION BY type ORDER BY COUNT(*) DESC) as rnk
    FROM netflix
    WHERE rating IS NOT NULL
    GROUP BY type, rating
)
SELECT type, rating, count
FROM RatingCounts
WHERE rnk = 1;

-- 3. List all movies released in a specific year (e.g., 2020)
select title, release_year from netflix where  type = 'Movie' and release_year = 2020 ;

-- 4. Find the top 5 countries with the most content on Netflix
select country, count(*) as total_content from netflix where country is not null
group by country order by total_content desc limit 5;

-- 5. Identify the longest movie or tv show duration.
select * from netflix where type = 'movie' and duration = (select Max(duration) from netflix);

-- 6. Find content added in the last 5 years
select * from netflix where str_to_date(date_added, 'Month DD, YYYY') >= current_date - interval 5 year;

-- 7. Find all the movies/TV shows by director 'Rajiv Chilaka'
select title, type, director 
from netflix where director = 'rajiv chilaka';

-- 8. List all TV shows with more than 5 seasons
SELECT * FROM netflix WHERE type = 'TV Show'
  AND CAST(SUBSTRING_INDEX(duration, ' ', 1) AS UNSIGNED) > 5;
  
-- 9. Count the number of content items in each genre
select listed_in, count(*) as total_content from netflix group by listed_in order by total_content desc;

-- 10.Find each year and the average numbers of content release in India on netflix. 
-- return top 5 year with highest avg content release
with yearly_content as (
select release_year, count(*) as total_content from netflix  where country = 'India' group by release_year)
select release_year, total_content, 
ROUND(AVG(total_content) OVER (), 2) AS avg_content_per_year
FROM yearly_content
order by total_content desc limit 5;

-- 11. List all movies that are documentaries
select * from netflix where listed_in like '%documentaries%';

-- 12. Find all content without a director
select * from netflix where director is null;

-- 13. Find how many movies actor 'Salman Khan' appeared in last 10 years!
select count(*) as total_movies from netflix where type = 'movie' and cast like '%salman khan%'
and release_year >= year(curdate()) - 10;

-- 14. Find the top 10 actors who have appeared in the highest number of movies produced in India.
SELECT cast, COUNT(*) as movie_count
FROM netflix
WHERE country LIKE '%India%' AND type = 'Movie' AND cast IS NOT NULL
GROUP BY cast
ORDER BY movie_count DESC
LIMIT 10;

-- 15. Categorize the content based on the presence of the keywords 'kill' and 'violence' in 
-- the description field. Label content containing these keywords as 'Bad' and all other 
-- content as 'Good'. Count how many items fall into each category.
select title,
case
when description like '&kill' or description like '%violence%' then 'Bad'
else 'good' 
end as category from netflix;
